use vstd::vec::Vec;
use vstd::prelude::*;

verus! {

    /// Given a non-empty index array `indices` and a non-empty matrix `choices`
    /// (each row of `choices` has the same length as `indices`),
    /// returns a new array `result` of the same length as `indices` such that
    /// for each i, result[i] = choices[ indices[i] as usize ][ i ].
    pub fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64>
        requires
            // The index array and matrix are non‐empty
            indices.len() > 0,
            choices.len() > 0,
            // Every row of the matrix has length = indices.len()
            forall(|r: usize| r < choices.len() ==> choices[r].len() == indices.len()),
            // Every index is a valid row selector
            forall(|i: usize| i < indices.len() ==> (indices[i] as usize) < choices.len()),
        ensures
            // The result has the same length as indices
            |res: Vec<f64>| res.len() == indices.len()
                // And picks out the correct element from `choices`
                && forall(|i: usize| i < indices.len() ==>
                              res[i] == choices[indices[i] as usize][i]),
    {
        let mut result: Vec<f64> = Vec::new();
        let mut i: usize = 0;

        // Build `result` element by element
        while i < indices.len() {
            invariant(i <= indices.len());
            invariant(result.len() == i);
            invariant(forall(|j: usize| j < i ==>
                                 result[j] == choices[indices[j] as usize][j]));
            decreases(indices.len() - i);

            let row: usize = indices[i] as usize;
            let v: f64 = choices[row][i];
            result.push(v);

            i += 1;
        }

        result
    }
}